 64	    private abstract static class MergeSorter {
 65	        final void sort(int left, int right) {
 66	            if (right - left < 2) {
 67	                return;
 68	            }
 69	
 70	            int mid = midpoint(left, right);
 71	            sort(left, mid);
 72	            sort(mid, right);
 73	            merge(left, mid, right);
 74	        }
 75	
 76	        abstract void merge(int left, int mid, int right);
 77	    }
 78	
 79	    private static final class IntMergeSorter extends MergeSorter {
 80	        private final int[] values;
 81	        private final int[] buffer;
 82	        private final int bufferOffset;
 83	
 84	        private IntMergeSorter(int[] values, int fromInclusive, int toExclusive) {
 85	            this.values = values;
 86	            this.buffer = new int[toExclusive - fromInclusive];
 87	            this.bufferOffset = fromInclusive;
 88	        }
 89	
 90	        @Override
 91	        void merge(int left, int mid, int right) {
 92	            int bufferLeft = left - bufferOffset;
 93	            System.arraycopy(values, left, buffer, bufferLeft, right - left);
 94	
 95	            int leftIndex = bufferLeft;
 96	            int leftEnd = bufferLeft + (mid - left);
 97	            int rightIndex = leftEnd;
 98	            int destIndex = left;
 99	            int bufferRight = bufferLeft + (right - left);
100	
101	            while (leftIndex < leftEnd && rightIndex < bufferRight) {
102	                if (buffer[leftIndex] <= buffer[rightIndex]) {
103	                    values[destIndex++] = buffer[leftIndex++];
104	                } else {
105	                    values[destIndex++] = buffer[rightIndex++];
106	                }
107	            }
108	
109	            while (leftIndex < leftEnd) {
110	                values[destIndex++] = buffer[leftIndex++];
111	            }
112	        }
113	    }
