115	    private static final class ObjectMergeSorter<T> extends MergeSorter {
116	        private final T[] values;
117	        private final Object[] buffer;
118	        private final Comparator<? super T> comparator;
119	
120	        private ObjectMergeSorter(T[] values, Comparator<? super T> comparator) {
121	            this.values = values;
122	            this.comparator = comparator;
123	            this.buffer = new Object[values.length];
124	        }
125	
126	        @Override
127	        void merge(int left, int mid, int right) {
128	            System.arraycopy(values, left, buffer, left, right - left);
129	
130	            int leftIndex = left;
131	            int rightIndex = mid;
132	            int destIndex = left;
133	            int leftEnd = mid;
134	            int bufferRight = right;
135	
136	            while (leftIndex < leftEnd && rightIndex < bufferRight) {
137	                @SuppressWarnings("unchecked")
138	                T leftValue = (T) buffer[leftIndex];
139	                @SuppressWarnings("unchecked")
140	                T rightValue = (T) buffer[rightIndex];
141	
142	                if (comparator.compare(leftValue, rightValue) <= 0) {
143	                    values[destIndex++] = leftValue;
144	                    leftIndex++;
145	                } else {
146	                    values[destIndex++] = rightValue;
147	                    rightIndex++;
148	                }
149	            }
150	
151	            while (leftIndex < leftEnd) {
152	                @SuppressWarnings("unchecked")
153	                T value = (T) buffer[leftIndex++];
154	                values[destIndex++] = value;
155	            }
156	        }
157	    }
